using System.ClientModel.Primitives;
using Azure;
using Azure.AI.OpenAI;
using Microsoft.SemanticKernel;

namespace ChatCompletion;

/// <summary>
/// This sample shows how to connect to Azure OpenAI using a custom <see cref="AzureOpenAIClient"/> configuration.
/// It demonstrates how to provide custom HTTP headers, configure timeouts, and define a retry policy.
/// </summary>
public sealed class AzureOpenAI_CustomClient(ITestOutputHelper output) : BaseTest(output)
{
    [Fact]
    public async Task RunAsync()
    {
        Console.WriteLine("======== Using a custom Azure OpenAI client ========");

        string endpoint = TestConfiguration.AzureOpenAI.Endpoint;
        string deploymentName = TestConfiguration.AzureOpenAI.ChatDeploymentName;
        string apiKey = TestConfiguration.AzureOpenAI.ApiKey;

        if (endpoint is null || deploymentName is null || apiKey is null)
        {
            Console.WriteLine("Azure OpenAI credentials not found. Skipping example.");
            return;
        }

        // Create an HttpClient and include your custom header(s).
        var httpClient = new HttpClient();
        httpClient.DefaultRequestHeaders.Add("My-Custom-Header", "My Custom Value");

        // Configure the AzureOpenAIClient options to use the customized HttpClient as transport,
        // apply a custom network timeout, and define a retry policy.
        var clientOptions = new AzureOpenAIClientOptions
        {
            Transport = new HttpClientPipelineTransport(httpClient),
            // Configure how long a single network operation is allowed to take before it is cancelled.
            NetworkTimeout = TimeSpan.FromSeconds(60),
            // Configure how many times a failed request is retried before giving up.
            RetryPolicy = new ClientRetryPolicy(maxRetries: 3),
        };

        var azureOpenAIClient = new AzureOpenAIClient(new Uri(endpoint), new AzureKeyCredential(apiKey), clientOptions);

        IKernelBuilder builder = Kernel.CreateBuilder();
        builder.AddAzureOpenAIChatCompletion(deploymentName, azureOpenAIClient);
        Kernel kernel = builder.Build();

        // Load semantic plugin defined with prompt templates
        string folder = RepoFiles.SamplePluginsPath();

        kernel.ImportPluginFromPromptDirectory(Path.Combine(folder, "FunPlugin"));

        // Run
        var result = await kernel.InvokeAsync(
            kernel.Plugins["FunPlugin"]["Excuses"],
            new() { ["input"] = "I have no homework" }
        );
        Console.WriteLine(result.GetValue<string>());

        httpClient.Dispose();
    }
}
